<script lang="ts">
  import { onMount } from 'svelte';
  import type { SceneOverview, OverviewPose } from './api';
  interface Props { overview: SceneOverview; selectedFrameId: string; lightingFilter: string; frustumLength: number; meshUrl?: string; showProxy: boolean; proxyOpacity: number; showStructural: boolean; showFurniture: boolean; showGraph: boolean; onSelect:(pose:OverviewPose)=>void; onHover:(pose:OverviewPose|null)=>void; }
  let { overview, selectedFrameId, lightingFilter, frustumLength, meshUrl = '', showProxy, proxyOpacity, showStructural, showFurniture, showGraph, onSelect, onHover }: Props = $props();
  let host = $state<HTMLDivElement>(); let destroy: (() => void) | null = null;
  onMount(async () => {
    const THREE = await import('three'); const { OrbitControls } = await import('three/examples/jsm/controls/OrbitControls.js'); const { GLTFLoader } = await import('three/examples/jsm/loaders/GLTFLoader.js'); if (!host) return;
    const scene=new THREE.Scene();scene.background=new THREE.Color('#061019');const camera=new THREE.PerspectiveCamera(55,1,.01,1000);const renderer=new THREE.WebGLRenderer({antialias:true});host.append(renderer.domElement);const orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=true;
    const box=new THREE.Box3(new THREE.Vector3(...overview.bounds.min),new THREE.Vector3(...overview.bounds.max));const center=box.getCenter(new THREE.Vector3()),span=Math.max(box.getSize(new THREE.Vector3()).length(),2);camera.position.set(center.x+span,center.y+span*.8,center.z+span);orbit.target.copy(center);scene.add(new THREE.GridHelper(span*2,20,0x38505e,0x1d303b));
    const graphGroup=new THREE.Group(),frustumGroup=new THREE.Group();scene.add(graphGroup);scene.add(frustumGroup);const edgePoints:number[]=[];for(const edge of overview.edges){const a=overview.nodes.find(n=>n.viewpoint_id===edge.source),b=overview.nodes.find(n=>n.viewpoint_id===edge.target);if(a&&b)edgePoints.push(...a.origin,...b.origin);}graphGroup.add(new THREE.LineSegments(new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(edgePoints,3)),new THREE.LineBasicMaterial({color:0x647d8f})));graphGroup.visible=showGraph;
    const visible=(p:OverviewPose)=>lightingFilter==='all'||p.lighting_id===lightingFilter;const colors=['#59d5cf','#f0b25b','#a884f5','#e2759c','#83c985'];const color=(id:string)=>new THREE.Color(colors[Math.abs([...id].reduce((a,c)=>a*31+c.charCodeAt(0),7))%colors.length]);const lookup:OverviewPose[]=[],hitPoints:number[]=[];
    for(const pose of overview.poses){if(!visible(pose))continue;const o=new THREE.Vector3(...pose.origin),t=new THREE.Vector3(...pose.target),f=t.clone().sub(o).normalize(),right=new THREE.Vector3().crossVectors(f,new THREE.Vector3(...pose.up)).normalize(),up=new THREE.Vector3().crossVectors(right,f).normalize(),d=frustumLength,w=Math.tan(pose.fov_deg*Math.PI/360)*d,h=w/pose.aspect,far=o.clone().addScaledVector(f,d),c=[far.clone().addScaledVector(right,w).addScaledVector(up,h),far.clone().addScaledVector(right,-w).addScaledVector(up,h),far.clone().addScaledVector(right,-w).addScaledVector(up,-h),far.clone().addScaledVector(right,w).addScaledVector(up,-h)],v:number[]=[];for(const corner of c)v.push(...o.toArray(),...corner.toArray());for(let i=0;i<4;i++)v.push(...c[i].toArray(),...c[(i+1)%4].toArray());frustumGroup.add(new THREE.LineSegments(new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(v,3)),new THREE.LineBasicMaterial({color:color(pose.lighting_id),transparent:true,opacity:pose.frame_id===selectedFrameId?1:.42})));hitPoints.push(...o.toArray());lookup.push(pose);}
    const points=new THREE.Points(new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(hitPoints,3)),new THREE.PointsMaterial({size:.10,color:0xffcb65}));points.userData.lookup=lookup;frustumGroup.add(points);
    if(meshUrl){try{const gltf=await new GLTFLoader().loadAsync(meshUrl);gltf.scene.traverse((child:any)=>{if(child.isMesh){const materialName=String(child.material?.name??'').toLowerCase();const structural=materialName.includes('structural');const furniture=materialName.includes('furniture');child.visible=(structural?showStructural:(furniture?showFurniture:true));child.material.transparent=proxyOpacity<.99;child.material.opacity=proxyOpacity;child.material.depthWrite=proxyOpacity>=.99;}});gltf.scene.visible=showProxy;scene.add(gltf.scene);}catch{/* legacy and unavailable proxy stay frustum-only */}}
    const ray=new THREE.Raycaster();ray.params.Points.threshold=.16;const pointer=new THREE.Vector2();function pick(e:PointerEvent,select:boolean){const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObject(points)[0],pose=hit&&hit.index!==undefined?points.userData.lookup[hit.index]:null;onHover(pose);if(select&&pose)onSelect(pose);}renderer.domElement.addEventListener('pointermove',(e:PointerEvent)=>pick(e,false));renderer.domElement.addEventListener('click',(e:PointerEvent)=>pick(e,true));
    function resize(){if(!host)return;renderer.setSize(host.clientWidth,host.clientHeight,false);camera.aspect=host.clientWidth/Math.max(host.clientHeight,1);camera.updateProjectionMatrix();}const observer=new ResizeObserver(resize);observer.observe(host);resize();let running=true;function tick(){if(!running)return;orbit.update();renderer.render(scene,camera);requestAnimationFrame(tick);}tick();destroy=()=>{running=false;observer.disconnect();orbit.dispose();renderer.dispose();renderer.domElement.remove();};
  });
  $effect(()=>()=>destroy?.());
</script>
<div bind:this={host} class="overview-three" aria-label="3D camera frustum overview"></div>
